// Battles and sieges.
//   place     : id from places.js or [lon, lat]
//   outcome   : 'allied' (American/French victory) | 'crown' (British/Loyalist victory) | 'draw'
//   allies / crown : commander ids from commanders.js that took part (only tracked commanders)
//   others    : notable participants who are not tracked on the map
//   strength / casualties : [allied, crown], approximate, from standard secondary sources
//   radiusKm  : optional; how far (km) participants may be from the marker (big sieges, fleets)
//   approach / withdrawal : days of each participant's route highlighted before/after the fight
window.SC = window.SC || {};
SC.battles = [
  { id: 'savannah1778', name: 'Capture of Savannah', kind: 'battle', start: '1778-12-29', end: '1778-12-29', place: [-81.08, 32.06],
    location: "Savannah, Chatham County, Georgia",
    outcome: 'crown', allies: [], crown: ['campbell'], others: 'Maj. Gen. Robert Howe (American)',
    strength: ['~850', '~3,100'], casualties: ['~83 killed, 453 captured', '7 killed, 19 wounded'], approach: 7, withdrawal: 2,
    summary: "Campbell's force from New York landed at Girardeau's Plantation. Guided by an enslaved man named Quamino Dolly along a hidden path through the swamp, they turned Howe's flank. The American defense collapsed and Savannah fell in an afternoon, opening the British Southern strategy." },

  { id: 'sunbury', name: 'Capture of Fort Morris (Sunbury)', kind: 'siege', start: '1779-01-06', end: '1779-01-09', place: 'sunbury',
    location: "Fort Morris State Historic Site, near Midway, Liberty County, Georgia",
    outcome: 'crown', allies: [], crown: ['prevost'], others: 'Maj. Joseph Lane (American garrison)',
    strength: ['~200', '~2,000'], casualties: ['~4 killed, ~7 wounded, ~200 captured', '~1 killed, ~3 wounded'], approach: 3, withdrawal: 7,
    summary: "Marching up from East Florida, Prevost surrounded the earthwork fort guarding Sunbury and bombarded it. Major Lane surrendered after a short siege. With Savannah already taken, all of coastal Georgia was now in British hands." },

  { id: 'port_royal', name: 'Port Royal Island (Beaufort)', kind: 'battle', start: '1779-02-03', end: '1779-02-03', place: 'port_royal_island',
    location: "Gray's Hill, Port Royal Island, near Beaufort, Beaufort County, S.C.",
    outcome: 'allied', allies: ['moultrie'], crown: [], others: 'Maj. Gardiner (British; first name given variously)',
    strength: ['~200–300 (sources differ)', '~200–320 (sources differ)'], casualties: ['8 killed, 22 wounded', '~40–50 killed and wounded, a few captured (sources differ)'], approach: 0, withdrawal: 0,
    summary: "A British landing party tried to seize Port Royal Island. Moultrie met it with Charleston militia and two field guns. After a long exchange, with both sides short of ammunition, the British fell back to their ships. It was one of the few Patriot successes of early 1779." },

  { id: 'kettle_creek', name: 'Kettle Creek', kind: 'battle', start: '1779-02-14', end: '1779-02-14', place: 'kettle_creek',
    location: "Near Washington, Wilkes County, Georgia",
    outcome: 'allied', allies: ['pickens', 'clarke'], crown: [], others: 'Col. John Dooly (American); Col. John Boyd (Loyalist, killed; some accounts call him James)',
    strength: ['~340–420', '~600–800'], casualties: ['9 killed, 23 wounded (some counts ~21 in all)', '~40–70 killed, ~75 wounded or captured (sources differ)'], approach: 4, withdrawal: 6,
    summary: "Pickens caught Boyd's Loyalists, who were marching to join Campbell, while they butchered cattle on Kettle Creek. Boyd was mortally wounded. The victory discouraged backcountry Loyalists and helped push Campbell out of Augusta." },

  { id: 'brier_creek', name: 'Brier Creek', kind: 'battle', start: '1779-03-03', end: '1779-03-03', place: 'brier_creek',
    location: "Brier Creek near Sylvania, Screven County, Georgia",
    outcome: 'crown', allies: [], crown: [], others: 'Gen. John Ashe (American); Lt. Col. Mark Prevost (British)',
    strength: ['~1,100–1,500 (sources differ)', '~900'], casualties: ['~150 killed or drowned, 227 captured', '5 killed, 11 wounded'], approach: 0, withdrawal: 0,
    summary: "Mark Prevost made a wide flank march and fell on Ashe's North Carolina militia from the rear. The Americans were trapped against the swamps of Brier Creek and the Savannah River and many drowned trying to escape. The defeat secured Georgia for the Crown." },

  { id: 'stono_ferry', name: 'Stono Ferry', kind: 'battle', start: '1779-06-20', end: '1779-06-20', place: 'stono_ferry',
    location: "Stono River near Rantowles, Charleston County, S.C.",
    outcome: 'crown', allies: ['lincoln'], crown: [], others: 'Lt. Col. John Maitland (British)',
    strength: ['~1,200', '~900'], casualties: ['34 killed, 113 wounded', '~130 killed and wounded'], approach: 6, withdrawal: 5,
    summary: "Lincoln attacked the rear guard Prevost had left at Stono Ferry as he withdrew from Charleston. After an hour of fighting Lincoln broke off as British reinforcements crossed from James Island. Andrew Jackson's brother Hugh died of heat exhaustion after the battle." },

  { id: 'siege_savannah', name: 'Siege of Savannah', kind: 'siege', start: '1779-09-16', end: '1779-10-18', place: 'savannah',
    location: "Savannah, Chatham County, Georgia",
    outcome: 'crown', allies: ['lincoln', 'destaing', 'huger'], crown: ['prevost'], others: 'Casimir Pulaski (mortally wounded); Sgt. William Jasper (killed)',
    strength: ['~7,700 French & American', '~3,200'], casualties: ['~244 killed, ~600 wounded in the 9 Oct assault', '~40 killed, ~63 wounded'], approach: 5, withdrawal: 6,
    summary: "D'Estaing's French army and Lincoln's Continentals besieged Savannah, and Prevost used the truce he asked for to strengthen his works. On 9 October the allies stormed the Spring Hill redoubt in fog and were slaughtered. It was one of the bloodiest single hours of the war. Among the French troops were the Chasseurs-Volontaires, free men of colour from Saint-Domingue." },

  { id: 'siege_charleston', name: 'Siege of Charleston', kind: 'siege', radiusKm: 25, start: '1780-03-29', end: '1780-05-12', place: 'charleston',
    location: "Charleston, S.C.",
    outcome: 'crown', allies: ['lincoln', 'moultrie'], crown: ['clinton', 'cornwallis', 'tarleton'], others: '',
    strength: ['~5,500', '~10,000–13,500'], casualties: ['89 killed, 138 wounded, ~5,000 captured', '76 killed, 189 wounded'], approach: 10, withdrawal: 5,
    summary: "Clinton's army landed on Simmons Island on 11 February, worked its way up the coast, crossed the Ashley and dug siege lines across Charleston Neck. Tarleton's victory at Monck's Corner closed the last escape route. Lincoln surrendered the city, the Southern Army and its stores on 12 May. It was the worst American defeat of the war." },

  { id: 'monks_corner', name: "Monck's Corner", kind: 'battle', start: '1780-04-14', end: '1780-04-14', place: 'biggin_bridge',
    location: "Moncks Corner, Berkeley County, S.C.",
    outcome: 'crown', allies: ['huger'], crown: ['tarleton'], others: 'Lt. Col. William Washington (American cavalry, escaped); Maj. Patrick Ferguson and Lt. Col. James Webster (British)',
    strength: ['~500', "~600 attacking (~1,400 with Webster's infantry in reserve)"], casualties: ['~20 killed, ~67 captured', '~3 wounded'], approach: 10, withdrawal: 3,
    summary: "In a night attack Tarleton surprised Huger's cavalry guarding Charleston's line of communication up the Cooper River. He captured some 400 horses and completed the encirclement of the city." },

  { id: 'lenuds_ferry', name: "Lenud's Ferry", kind: 'battle', start: '1780-05-06', end: '1780-05-06', place: 'lenuds_ferry',
    location: "Santee River near Jamestown, Berkeley County, S.C.",
    outcome: 'crown', allies: [], crown: ['tarleton'], others: 'Col. Anthony White (American)',
    strength: ['~350', '~150'], casualties: ['~40 killed/wounded, 67 captured', '2 killed'], approach: 3, withdrawal: 3,
    summary: "Tarleton caught the remnants of the Continental cavalry resting at the Santee crossing and scattered them. The last mounted force near Charleston was gone." },

  { id: 'waxhaws', name: 'Waxhaws (Buford\'s Massacre)', kind: 'battle', start: '1780-05-29', end: '1780-05-29', place: 'waxhaws',
    location: "Near Buford, Lancaster County, S.C.",
    outcome: 'crown', allies: [], crown: ['tarleton'], others: 'Col. Abraham Buford (American)',
    strength: ['~420', '~270'], casualties: ['113 killed, 150 wounded, 53 captured', '5 killed, 12 wounded'], approach: 3, withdrawal: 4,
    summary: "Tarleton rode about 105 miles in 54 hours to catch Buford's retreating Virginians. Many Americans were cut down after trying to surrender. \"Tarleton's Quarter\" became a rallying cry for backcountry Patriots." },

  { id: 'alexanders_old_field', name: "Alexander's Old Field", kind: 'battle', start: '1780-06-06', end: '1780-06-06', place: 'alexanders_old_field',
    location: "Beckhamville, about 3 miles north of Great Falls, Chester County, S.C. (state marker at S.C. 97 and S.C. 99)",
    outcome: 'allied', allies: [], crown: [], others: 'Capt. John McClure and the Gaston brothers (Patriot militia); Col. Henry Houseman (Loyalist)',
    strength: ['~32', '~200'], casualties: ['2 wounded (some accounts say a few killed)', 'unknown; a few killed'], approach: 0, withdrawal: 0,
    summary: "A week after the Waxhaws, Loyalists gathered at Alexander's Old Field to swear allegiance to the King. Captain John McClure and about 32 neighbours, among them old Judge John Gaston and his sons, charged the assembly and scattered it. It is counted the first Patriot victory in South Carolina after the fall of Charleston." },

  { id: 'ramsours_mill', name: "Ramsour's Mill", kind: 'battle', start: '1780-06-20', end: '1780-06-20', place: 'ramsours_mill',
    location: "Lincolnton, Lincoln County, N.C.",
    outcome: 'allied', allies: [], crown: [], others: 'Col. Francis Locke (Patriot militia); Col. John Moore (Loyalist militia)',
    strength: ['~400', '~1,300'], casualties: ['~70 killed, ~100 wounded', '~70 killed, ~100 wounded'], approach: 0, withdrawal: 0,
    summary: "A fight between neighbours: Patriot militia attacked a gathering of Loyalists. Few on either side wore uniforms, and men marked themselves with paper or sprigs of green. The Loyalist rising in western North Carolina collapsed." },

  { id: 'hucks_defeat', name: "Huck's Defeat", kind: 'battle', start: '1780-07-12', end: '1780-07-12', place: 'hucks_defeat',
    location: "Williamson's Plantation (Historic Brattonsville), York County, S.C.",
    outcome: 'allied', allies: [], crown: [], others: 'Col. William Bratton & Capt. John McClure (Patriot); Capt. Christian Huck (British Legion, killed)',
    strength: ['~140–250 (sources differ)', '~115'], casualties: ['1 killed', '~35 killed, ~30 wounded'], approach: 0, withdrawal: 0,
    summary: "Backcountry militia surprised Huck's detachment at dawn at Williamson's Plantation. It was the first Patriot victory after the fall of Charleston and drew volunteers to Sumter." },

  { id: 'rocky_mount', name: 'Rocky Mount', kind: 'battle', start: '1780-07-30', end: '1780-07-30', place: 'rocky_mount',
    location: "Catawba River near Great Falls, Chester County, S.C.",
    outcome: 'crown', allies: ['sumter'], crown: [], others: 'Lt. Col. George Turnbull (Loyalist)',
    strength: ['~600', '~300'], casualties: ['~12 killed', '~10 killed'], approach: 10, withdrawal: 5,
    summary: "Sumter attacked the fortified Loyalist post but could not carry its log buildings, even with a fire wagon. He withdrew to try Hanging Rock a week later." },

  { id: 'hanging_rock', name: 'Hanging Rock', kind: 'battle', start: '1780-08-06', end: '1780-08-06', place: 'hanging_rock',
    location: "Near Heath Springs, Lancaster County, S.C.",
    outcome: 'allied', allies: ['sumter'], crown: [], others: 'Maj. John Carden (Loyalist); 13-year-old Andrew Jackson present',
    strength: ['~800', '~1,400'], casualties: ['12 killed, 41 wounded', '~200 killed and wounded'], approach: 5, withdrawal: 5,
    summary: "Sumter's militia routed part of the Loyalist camp. Discipline then broke down as his men plundered the British stores and rum, and Sumter had to withdraw before the victory was complete. It is still counted an American victory: the Loyalist camp was broken and its losses were four times Sumter's." },

  { id: 'lynches_standoff', name: 'Standoff at Little Lynches Creek', kind: 'standoff', start: '1780-08-11', end: '1780-08-12', place: 'lynches_creek',
    location: "Little Lynches Creek, Kershaw County, S.C. (about 15 miles northeast of Camden)",
    outcome: 'draw', allies: ['gates', 'dekalb'], crown: ['rawdon'], others: '',
    strength: ['~3,000', '~1,000'], casualties: ['None (no fighting)', 'None (no fighting)'], approach: 8, withdrawal: 3,
    summary: "Rawdon took up a strong position on the far bank of Little Lynches Creek to block Gates's road to Camden. The armies faced each other but did not fight. Gates would not attack across the creek and instead swung north to Rugeley's Mill. Rawdon fell back to Camden, where Cornwallis was arriving, which set up the Battle of Camden four days later." },

  { id: 'camden', name: 'Battle of Camden', kind: 'battle', start: '1780-08-16', end: '1780-08-16', place: 'camden_field',
    location: "About 7 miles north of Camden, Kershaw County, S.C.",
    outcome: 'crown', allies: ['gates', 'dekalb', 'owilliams'], crown: ['cornwallis', 'rawdon', 'tarleton'], others: '',
    strength: ['~3,700', '~2,100'], casualties: ['~900 killed and wounded, ~1,000 captured', '68 killed, 245 wounded'], approach: 20, withdrawal: 3,
    summary: "The two armies ran into each other on a night march and fought at dawn. Gates had placed raw Virginia and North Carolina militia opposite Cornwallis's best regulars, and they broke without firing. De Kalb's Marylanders and Delawares fought on until surrounded. Gates fled 60 miles to Charlotte on a fast horse. It was one of the worst defeats ever suffered by an American army." },

  { id: 'fishing_creek', name: 'Fishing Creek', kind: 'battle', start: '1780-08-18', end: '1780-08-18', place: 'fishing_creek',
    location: "Near the Catawba River, about 2 miles north of Great Falls, Chester County, S.C.",
    outcome: 'crown', allies: ['sumter'], crown: ['tarleton'], others: '',
    strength: ['~800', '~160'], casualties: ['~150 killed, ~300 captured', '16 killed and wounded'], approach: 2, withdrawal: 6,
    summary: "Two days after Camden, Tarleton caught Sumter's men resting with their arms stacked. Sumter escaped half-dressed and bareback." },

  { id: 'musgrove_mill', name: 'Musgrove Mill', kind: 'battle', start: '1780-08-19', end: '1780-08-19', place: 'musgrove_mill',
    location: "Enoree River near Cross Anchor, Laurens/Spartanburg counties, S.C.",
    outcome: 'allied', allies: ['clarke'], crown: [], others: 'Col. Isaac Shelby, Col. James Williams (Patriot); Col. Alexander Innes (Loyalist)',
    strength: ['~200', '~500'], casualties: ['4 killed, 12 wounded', '63 killed, 90 wounded, 70 captured'], approach: 1, withdrawal: 12,
    summary: "The Patriots threw up a breastwork and lured the Loyalists into attacking it, then shattered them. Learning of Camden, they escaped with their prisoners over the mountains." },

  { id: 'great_savannah', name: 'Great Savannah', kind: 'battle', start: '1780-08-20', end: '1780-08-20', place: 'great_savannah',
    location: "Great Savannah, by Nelson's Ferry on the Santee (now Lake Marion), Clarendon County, S.C.",
    outcome: 'allied', allies: ['marion'], crown: [], others: '',
    strength: ['~50', '~40 guards'], casualties: ['1 wounded', '~22 captured'], approach: 3, withdrawal: 7,
    summary: "Marion struck a British escort at Nelson's Ferry and freed about 150 Maryland Continentals captured at Camden. It was his first notable action as a partisan leader." },

  { id: 'blue_savannah', name: 'Blue Savannah', kind: 'battle', start: '1780-09-04', end: '1780-09-04', place: 'blue_savannah',
    location: "Blue Savannah, near the Little Pee Dee SE of Marion, Marion County, S.C. (approximate: about 3 miles north of the state marker on U.S. 501, as its text describes)",
    outcome: 'allied', allies: ['marion'], crown: [], others: 'Maj. Micajah Ganey and Capt. Jesse Barfield (Loyalist)',
    strength: ['~50–60', '~250'], casualties: ['4 wounded', '~30–50 killed or wounded'], approach: 6, withdrawal: 4,
    summary: "Marion first scattered Ganey's advance guard in a dawn charge. Facing Barfield's larger main body, he then feigned a retreat and drew it into an ambush at a Carolina bay called Blue Savannah, where the Loyalists broke and fled. The win brought about sixty new volunteers to Marion." },

  { id: 'augusta1780', name: 'First Siege of Augusta', kind: 'siege', start: '1780-09-14', end: '1780-09-18', place: 'augusta',
    location: "Augusta, Richmond County, Georgia",
    outcome: 'crown', allies: ['clarke'], crown: ['brown', 'cruger'], others: '',
    strength: ['~600', '~500'], casualties: ['~60', '~40'], approach: 5, withdrawal: 10,
    summary: "Clarke trapped Brown and his garrison in the Mackay trading house (the \"White House\"). Brown held out although wounded until Cruger arrived from Ninety Six. Afterwards Loyalists hanged several captured Patriots." },

  { id: 'black_mingo', name: 'Black Mingo', kind: 'battle', start: '1780-09-28', end: '1780-09-28', place: 'black_mingo',
    location: "Black Mingo Creek near Rhems, Williamsburg County, S.C.",
    outcome: 'allied', allies: ['marion'], crown: [], others: 'Col. John Coming Ball (Loyalist)',
    strength: ['~50', '~50'], casualties: ['~8 killed and wounded', '~30 killed and wounded'], approach: 5, withdrawal: 5,
    summary: "Marion's night attack on Ball's Loyalists at Dollard's Tavern. Marion took Ball's horse, which he rode for the rest of the war, and from then on muffled his horses' hooves on night marches." },

  { id: 'kings_mountain', name: 'Kings Mountain', kind: 'battle', start: '1780-10-07', end: '1780-10-07', place: 'kings_mountain',
    location: "Near Blacksburg, York County, S.C.",
    outcome: 'allied', allies: ['overmountain'], crown: ['ferguson'], others: 'Cols. William Campbell, Isaac Shelby, John Sevier, Benjamin Cleveland',
    strength: ['~900', '~1,100'], casualties: ['28 killed, 62 wounded', '~290 killed, ~163 wounded, ~668 captured'], approach: 12, withdrawal: 7,
    summary: "Frontier riflemen surrounded the wooded ridge and fought their way up from all sides. Ferguson was shot from his horse. Every man in his force was killed or captured. Cornwallis abandoned his first invasion of North Carolina, and Jefferson later called the battle \"the turn of the tide of success\"." },

  { id: 'tearcoat', name: 'Tearcoat Swamp', kind: 'battle', start: '1780-10-25', end: '1780-10-25', place: 'tearcoat',
    location: "Tearcoat Swamp (Tearcoat Branch of the Black River), south of Turbeville, Clarendon County, S.C. (approximate)",
    outcome: 'allied', allies: ['marion'], crown: [], others: 'Col. Samuel Tynes (Loyalist)',
    strength: ['~150', '~200'], casualties: ['none', '~6 killed, 14 wounded, 23 captured'], approach: 7, withdrawal: 10,
    summary: "Marion's midnight attack scattered a Loyalist militia muster and captured the muskets and supplies meant to arm it." },

  { id: 'fishdam_ford', name: 'Fishdam Ford', kind: 'battle', start: '1780-11-09', end: '1780-11-09', place: 'fishdam_ford',
    location: "Broad River near Carlisle, Chester County, S.C.",
    outcome: 'allied', allies: ['sumter'], crown: [], others: 'Maj. James Wemyss (British, wounded & captured)',
    strength: ['~500', '~140'], casualties: ['~4 killed', '~20 killed and wounded'], approach: 7, withdrawal: 7,
    summary: "Wemyss led a night attack on Sumter's camp, but the Patriots were ready for it. Wemyss was wounded and captured, and Sumter himself narrowly escaped capture." },

  { id: 'blackstocks', name: "Blackstock's Plantation", kind: 'battle', start: '1780-11-20', end: '1780-11-20', place: 'blackstocks',
    location: "Tyger River near Cross Keys, Union County, S.C.",
    outcome: 'allied', allies: ['sumter'], crown: ['tarleton'], others: '',
    strength: ['~1,000', '~270'], casualties: ['3 killed, 4 wounded (incl. Sumter)', "~50 (Tarleton's report) to ~190 (American claims) killed and wounded"], approach: 8, withdrawal: 5,
    summary: "Tarleton outran his own infantry and attacked Sumter's strong position with only part of his force. He was repulsed. Sumter was badly wounded in the shoulder." },

  { id: 'rugeleys_mill', name: "Rugeley's Mill", kind: 'battle', start: '1780-12-04', end: '1780-12-04', place: [-80.6424, 34.4053],
    location: "Clermont, Henry Rugeley's plantation, about 13 miles north of Camden, Kershaw County, S.C.",
    outcome: 'allied', allies: [], crown: [], others: 'Lt. Col. William Washington (American cavalry); Col. Henry Rugeley (Loyalist)',
    strength: ['~80 cavalry', '~114'], casualties: ['none', '114 captured'], approach: 0, withdrawal: 0,
    summary: "Rugeley's Loyalists held a fortified log barn that Washington's dragoons could not take without artillery. Washington had a pine log shaped and blackened to look like a cannon, set it on wheels in full view and called on the garrison to surrender before he opened fire. Rugeley gave up without a shot: 114 men, their muskets and wagons. The barn was burned." },

  { id: 'halfway_swamp', name: 'Halfway Swamp', kind: 'battle', start: '1780-12-12', end: '1780-12-13', place: 'halfway_swamp',
    location: "Halfway Swamp, near Rimini, Clarendon County, S.C. (approximate; by tradition)",
    outcome: 'draw', allies: ['marion'], crown: [], others: 'Maj. Robert McLeroth (64th Foot)',
    strength: ['~700', '~400 (the 64th Foot and ~200 recruits)'], casualties: ['a few wounded (sources differ)', '~6 killed'], approach: 6, withdrawal: 5,
    summary: "Marion caught McLeroth's column of new recruits marching to join Cornwallis and blocked its road. McLeroth proposed settling it with a duel of twenty picked men a side, then slipped away in the night while Marion waited. Marion broke off after learning there was smallpox at nearby Singleton's Mill, and the British reached Winnsboro." },

  { id: 'hammonds_store', name: "Hammond's Store", kind: 'battle', start: '1780-12-30', end: '1780-12-30', place: 'hammonds_store',
    location: "Near Clinton, Laurens County, S.C.",
    outcome: 'allied', allies: ['wwashington'], crown: [], others: 'Col. Thomas Waters (Loyalist)',
    strength: ['~280', '~250'], casualties: ['none', '~150 killed and wounded, 40 captured'], approach: 4, withdrawal: 3,
    summary: "Washington's dragoons and mounted militia, detached by Morgan, routed Georgia Loyalists. The raid alarmed Cornwallis about Ninety Six, and he sent Tarleton after Morgan." },

  { id: 'cowpens', name: 'Battle of Cowpens', kind: 'battle', start: '1781-01-17', end: '1781-01-17', place: 'cowpens',
    location: "Near Chesnee, Cherokee County, S.C.",
    outcome: 'allied', allies: ['morgan', 'pickens', 'wwashington'], crown: ['tarleton'], others: 'Lt. Col. John Eager Howard (Continental infantry)',
    strength: ['~1,050', '~1,100'], casualties: ['25 killed, 124 wounded', '~110 killed, ~229 wounded, ~600 captured'], approach: 17, withdrawal: 6,
    summary: "Morgan placed his militia in front and asked them only for \"two fires\" before retiring. The British pursued them straight into the Continental line, while Washington's dragoons and Pickens's reformed militia closed on both flanks. The result was a complete double envelopment, one of the most complete tactical victories of the war. Tarleton escaped with only a few hundred men." },

  { id: 'georgetown_raid', name: 'Raid on Georgetown', kind: 'raid', start: '1781-01-24', end: '1781-01-24', place: 'georgetown',
    location: "Georgetown, S.C.",
    outcome: 'draw', allies: ['marion', 'lee'], crown: [], others: 'Lt. Col. George Campbell (British, captured)',
    strength: ['~400', '~200'], casualties: ['light', 'several killed; commander captured'], approach: 12, withdrawal: 4,
    summary: "In a combined raid, Lee's infantry came downriver by boat while Marion's men attacked by land. They captured the garrison commander but could not take the fortified post." },

  { id: 'cowans_ford', name: "Cowan's Ford", kind: 'battle', start: '1781-02-01', end: '1781-02-01', place: 'cowans_ford',
    location: "Catawba River near Huntersville, N.C. (now under Lake Norman)",
    outcome: 'crown', allies: [], crown: ['cornwallis'], others: 'Gen. William Lee Davidson (American, killed)',
    strength: ['~300 at the ford (of ~800 guarding the crossings)', '~2,500'], casualties: ['~4 killed incl. Davidson', '~4 killed, 36 wounded'], approach: 7, withdrawal: 3,
    summary: "Cornwallis forced a crossing of the swollen Catawba before dawn, wading chest-deep under militia fire. Davidson was killed and the militia scattered, opening the road east after Greene." },

  { id: 'race_to_dan', name: 'Race to the Dan', kind: 'campaign', start: '1781-02-10', end: '1781-02-14', place: 'irwins_ferry',
    location: "Irwin's and Boyd's ferries on the Dan River near South Boston, Halifax County, Va.",
    outcome: 'allied', allies: ['greene', 'lee', 'owilliams', 'huger'], crown: ['cornwallis', 'tarleton'], others: '',
    strength: ['~2,000', '~2,500'], casualties: ['—', 'heavy straggling and attrition'], approach: 4, withdrawal: 6,
    summary: "Otho Williams's light troops lured Cornwallis west while Greene's army marched hard for the Dan. Greene had collected every boat on the river in advance. When the British reached the Dan the Americans were all across, leaving Cornwallis exhausted, far from his supplies and in hostile country." },

  { id: 'pyles', name: "Pyle's Defeat", kind: 'battle', start: '1781-02-25', end: '1781-02-25', place: 'pyles',
    location: "Near Burlington, Alamance County, N.C.",
    outcome: 'allied', allies: ['lee', 'pickens'], crown: [], others: 'Col. John Pyle (Loyalist, wounded)',
    strength: ['~600', '~400'], casualties: ['1 horse killed', '~90–250 killed (sources differ), many wounded'], approach: 7, withdrawal: 7,
    summary: "Pyle's Loyalists mistook Lee's green-jacketed Legion for Tarleton's men. When the error came out, the Legion cut them down. The slaughter frightened North Carolina Loyalists away from Cornwallis." },

  { id: 'weitzels_mill', name: "Weitzel's Mill", kind: 'battle', start: '1781-03-06', end: '1781-03-06', place: 'weitzels_mill',
    location: "Reedy Fork Creek, northern Guilford County, N.C.",
    outcome: 'draw', allies: ['lee', 'wwashington', 'owilliams'], crown: ['cornwallis', 'tarleton'], others: "Lt. Col. James Webster (British)",
    strength: ['~700', '~1,200'], casualties: ['~20–50 killed and wounded (sources differ)', '~21–30 killed and wounded'], approach: 5, withdrawal: 5,
    summary: "Cornwallis tried to catch Otho Williams's light corps, which was screening Greene, at the ford over Reedy Fork. Webster forced the crossing under rifle fire and the Americans fell back in good order. Nine days later the two armies met at Guilford Courthouse." },

  { id: 'wiboo_lower_bridge', name: 'Wiboo Swamp & Lower Bridge', kind: 'battle', start: '1781-03-06', end: '1781-03-13', place: 'lower_bridge',
    location: "Wyboo Swamp (the causeway is now under Lake Marion) to the Lower Bridge on the Black River near Kingstree, Clarendon & Williamsburg counties, S.C.",
    outcome: 'allied', allies: ['marion'], crown: [], others: 'Lt. Col. John Watson (British)',
    strength: ['~300–400', '~500'], casualties: ['light (sources differ)', 'light to moderate (sources differ)'], approach: 6, withdrawal: 15,
    summary: "Watson marched a column up the Santee to destroy Marion's brigade. Marion fought him at Wiboo Swamp and then held the Lower Bridge over the Black River, where his riflemen picked off anyone trying to cross. Watson gave up and fell back to Georgetown. Meanwhile a second column under Doyle found and burned Snow's Island." },

  { id: 'guilford', name: 'Guilford Courthouse', kind: 'battle', start: '1781-03-15', end: '1781-03-15', place: 'guilford',
    location: "Greensboro, Guilford County, N.C.",
    outcome: 'crown', allies: ['greene', 'lee', 'wwashington', 'owilliams', 'huger'], crown: ['cornwallis', 'tarleton'], others: '',
    strength: ['~4,400', '~1,900'], casualties: ['79 killed, 185 wounded (plus ~1,000 militia missing)', '93 killed, 413 wounded, 26 missing'], approach: 10, withdrawal: 5,
    summary: "Greene copied Morgan's layered defence on a larger scale with three lines. Cornwallis broke through only after firing grapeshot into the melee, hitting his own Guards. He held the field but lost a quarter of his army. \"Another such victory would ruin the British Army,\" said Charles James Fox in Parliament." },

  { id: 'beatties_mill', name: "Beattie's Mill", kind: 'battle', start: '1781-03-21', end: '1781-03-21', place: 'beatties_mill',
    location: "Little River, west of Due West, Abbeville County, S.C. (approximate)",
    outcome: 'allied', allies: [], crown: [], others: 'Col. Elijah Clarke and Lt. Col. James McCall (Patriot); Maj. James Dunlap (Loyalist, captured)',
    strength: ['~180', '~90'], casualties: ['none reported', '34 killed and wounded, 42 captured'], approach: 0, withdrawal: 0,
    summary: "Clarke's Georgians and McCall's South Carolinians caught Major James Dunlap's Loyalist dragoons foraging at Beattie's Mill. A party seized the bridge behind them, and after several hours Dunlap surrendered. He was murdered as a prisoner a few days later; Pickens denounced the killing to the British commander at Ninety Six and offered a reward for the killers." },

  { id: 'fort_watson', name: 'Siege of Fort Watson', kind: 'siege', start: '1781-04-15', end: '1781-04-23', place: 'fort_watson',
    location: "Scott's Lake near Summerton, Clarendon County, S.C. (Santee National Wildlife Refuge)",
    outcome: 'allied', allies: ['marion', 'lee'], crown: [], others: 'Lt. James McKay (British)',
    strength: ['~380', '~120'], casualties: ['2 killed, 6 wounded', '~114 captured'], approach: 7, withdrawal: 7,
    summary: "The fort stood on an old Indian mound and had no artillery to fear. Hezekiah Maham designed a log tower that rose above its walls, and riflemen firing down from it forced the garrison to surrender." },

  { id: 'blandford', name: 'Blandford (Petersburg)', kind: 'battle', start: '1781-04-25', end: '1781-04-25', place: [-77.3885, 37.2262],
    location: "Blandford, east side of Petersburg, Va.",
    outcome: 'crown', allies: ['steuben'], crown: ['phillips', 'arnold'], others: 'Brig. Gen. Peter Muhlenberg (American)',
    strength: ['~1,000 militia', '~2,500'], casualties: ['~60–150 (sources differ)', '~20–60 (sources differ)'], approach: 3, withdrawal: 6,
    summary: "Steuben's Virginia militia made a stand at Blandford to delay Phillips and Arnold. They held for several hours before retiring in good order across the Appomattox. The British went on to destroy the Virginia navy at Osborne's two days later." },

  { id: 'hobkirk', name: "Hobkirk's Hill", kind: 'battle', start: '1781-04-25', end: '1781-04-25', place: 'hobkirk',
    location: "Camden, Kershaw County, S.C.",
    outcome: 'crown', allies: ['greene', 'wwashington', 'owilliams', 'huger'], crown: ['rawdon'], others: '',
    strength: ['~1,550', '~900'], casualties: ['19 killed, 113 wounded, 136 missing', '38 killed, ~220 wounded and missing'], approach: 6, withdrawal: 4,
    summary: "Rawdon attacked Greene's camp outside Camden on a narrow front. Greene's counterattack fell apart when the veteran 1st Maryland fell into confusion. Rawdon won the field but abandoned Camden two weeks later." },

  { id: 'fort_motte', name: 'Siege of Fort Motte', kind: 'siege', start: '1781-05-06', end: '1781-05-12', place: 'fort_motte',
    location: "Near St. Matthews, Calhoun County, S.C.",
    outcome: 'allied', allies: ['marion', 'lee'], crown: [], others: 'Rebecca Motte (owner of the mansion); Lt. Donald McPherson (British)',
    strength: ['~400', '~180'], casualties: ['2 killed', '~180 captured'], approach: 6, withdrawal: 3,
    summary: "The British had fortified Rebecca Motte's mansion. She approved burning her own house, and fire arrows set the roof alight, forcing the garrison out. Afterwards she served dinner to both sides' officers." },

  { id: 'fort_granby', name: 'Fort Granby', kind: 'siege', start: '1781-05-15', end: '1781-05-15', place: 'fort_granby',
    location: "Cayce, Lexington County, S.C.",
    outcome: 'allied', allies: ['lee', 'sumter'], crown: [], others: 'Maj. Andrew Maxwell (Loyalist)',
    strength: ['~400', '~350'], casualties: ['none', '~350 captured'], approach: 3, withdrawal: 6,
    summary: "Lee reached the post on the Congaree before Sumter could return. He bluffed the garrison into surrendering, allowing them to keep their plunder." },

  { id: 'fort_galphin', name: 'Fort Galphin', kind: 'siege', start: '1781-05-21', end: '1781-05-21', place: 'fort_galphin',
    location: "Silver Bluff on the Savannah River, near Jackson, Aiken County, S.C.",
    outcome: 'allied', allies: ['lee'], crown: [], others: 'Capt. Michael Rudulph (Lee\'s Legion)',
    strength: ['~200', '~120'], casualties: ['1 dead of heat', 'garrison captured'], approach: 6, withdrawal: 1,
    summary: "On a sweltering day Lee's Legion surprised the fortified trading post below Augusta and captured its garrison. They also took the British army's annual gifts for the Creek and Cherokee, including powder, arms and blankets, just before the siege of Augusta." },

  { id: 'augusta1781', name: 'Siege of Augusta', kind: 'siege', start: '1781-05-22', end: '1781-06-05', place: 'augusta',
    location: "Augusta, Richmond County, Georgia",
    outcome: 'allied', allies: ['lee', 'pickens', 'clarke'], crown: ['brown'], others: '',
    strength: ['~1,600', '~600'], casualties: ['~50', '~52 killed, 334 captured'], approach: 3, withdrawal: 4,
    summary: "After Clarke's month-long blockade, Lee and Pickens arrived and took Fort Grierson. They then built a Maham tower and fired cannon from it into Fort Cornwallis until Brown surrendered." },

  { id: 'ninety_six', name: 'Siege of Ninety-Six', kind: 'siege', radiusKm: 40, start: '1781-05-22', end: '1781-06-19', place: 'ninety_six',
    location: "Ninety Six, Greenwood County, S.C.",
    outcome: 'crown', allies: ['greene', 'lee', 'wwashington', 'owilliams'], crown: ['cruger', 'rawdon'], others: 'Col. Thaddeus Kosciuszko (engineer)',
    strength: ['~1,000–1,500 (with militia)', '~550'], casualties: ['~57 killed, ~70 wounded', '~27 killed, ~58 wounded'], approach: 7, withdrawal: 6,
    summary: "Kosciuszko dug approach trenches toward the earthen Star Fort, but the Loyalist garrison held out for 28 days. When Rawdon's relief column drew near, Greene's assault of 18 June failed and he lifted the siege. The British abandoned Ninety Six weeks later anyway." },

  { id: 'charlottesville', name: 'Charlottesville Raid', kind: 'raid', start: '1781-06-04', end: '1781-06-04', place: 'charlottesville',
    location: "Charlottesville, Albemarle County, Va.",
    outcome: 'crown', allies: [], crown: ['tarleton'], others: 'Jack Jouett (rider); Thomas Jefferson',
    strength: ['—', '~250'], casualties: ['7 legislators captured', '—'], approach: 4, withdrawal: 6,
    summary: "Tarleton raced to capture the Virginia legislature. Jack Jouett rode 40 miles through the night to warn them, and Jefferson escaped Monticello minutes ahead of the dragoons." },

  { id: 'green_spring', name: 'Green Spring', kind: 'battle', start: '1781-07-06', end: '1781-07-06', place: 'green_spring',
    location: "Near Jamestown, James City County, Va.",
    outcome: 'crown', allies: ['lafayette', 'wayne'], crown: ['cornwallis', 'tarleton'], others: '',
    strength: ['~900 engaged', '~5,000 engaged of ~7,000'], casualties: ['28 killed, 99 wounded, 12 missing', '~75 killed and wounded'], approach: 10, withdrawal: 7,
    summary: "Cornwallis made it look as if only his rear guard remained on the north bank of the James. Wayne attacked and found the whole British army. He saved his men by charging straight at the enemy before falling back." },

  { id: 'quinby', name: 'Quinby Bridge', kind: 'battle', start: '1781-07-17', end: '1781-07-17', place: 'quinby',
    location: "Near Huger, Berkeley County, S.C.",
    outcome: 'crown', allies: ['sumter', 'marion', 'lee'], crown: [], others: 'Lt. Col. James Coates (British)',
    strength: ['~1,000', '~500'], casualties: ['~60 killed and wounded', '~6 killed'], approach: 7, withdrawal: 8,
    summary: "The climax of Sumter's \"Dog Days Expedition\". He sent Marion's men against Coates's well-posted troops at Shubrick's Plantation, and they took heavy losses. Marion and Lee left Sumter in disgust." },

  { id: 'parkers_ferry', name: "Parker's Ferry", kind: 'battle', start: '1781-08-30', end: '1781-08-30', place: 'parkers_ferry',
    location: "Edisto River near Jacksonboro, Colleton County, S.C.",
    outcome: 'allied', allies: ['marion'], crown: [], others: 'Maj. Thomas Fraser (Loyalist)',
    strength: ['~400', '~500'], casualties: ['~5 killed', '~125–200 killed and wounded (sources differ)'], approach: 10, withdrawal: 9,
    summary: "Marion's men lay hidden along a causeway through the swamp. Fraser's Loyalist cavalry charged down it repeatedly into point-blank fire." },

  { id: 'capes', name: 'Battle of the Capes', kind: 'naval', start: '1781-09-05', end: '1781-09-05', place: [-75.65, 36.85],
    location: "Off the Virginia Capes, at the mouth of Chesapeake Bay",
    outcome: 'allied', allies: ['degrasse'], crown: [], others: 'Adm. Thomas Graves (British)',
    strength: ['24 ships of the line', '19 ships of the line'], casualties: ['~220', '~336'], approach: 6, withdrawal: 6,
    summary: "A tactically indecisive fight off the mouth of the Chesapeake. Graves then withdrew to New York, leaving the French in control of the bay. No Royal Navy rescue would reach Cornwallis." },

  { id: 'eutaw', name: 'Eutaw Springs', kind: 'battle', start: '1781-09-08', end: '1781-09-08', place: 'eutaw',
    location: "Near Eutawville, Orangeburg County, S.C.",
    outcome: 'draw', allies: ['greene', 'marion', 'pickens', 'lee', 'wwashington', 'owilliams'], crown: ['stewart', 'cruger'], others: '',
    strength: ['~2,200', '~2,000'], casualties: ['138 killed, 375 wounded, 41 missing', "85 killed, 351 wounded, 257 missing (Stewart's return; Americans counted up to ~500 prisoners)"], approach: 17, withdrawal: 3,
    summary: "Greene's attack drove the British back through their own camp. His hungry troops then stopped to plunder the tents and rum, and a counterattack from a fortified brick house restored the line. Stewart held the field but withdrew toward Charleston. It was the last major battle in the Carolinas." },

  { id: 'the_hook', name: 'The Hook (Gloucester)', kind: 'battle', start: '1781-10-03', end: '1781-10-03', place: [-76.5028, 37.2761],
    location: "About 3 miles north of Gloucester Point, Gloucester County, Va.",
    outcome: 'allied', allies: [], crown: ['tarleton'], others: "Duc de Lauzun (French legion); Brig. Gen. George Weedon and Lt. Col. John Mercer (Virginia militia)",
    strength: ['~600 cavalry & infantry engaged', '~400'], casualties: ['3 French killed, 16 wounded, plus a few militia', '~12–50 killed, wounded and captured (sources differ)'], approach: 4, withdrawal: 16,
    summary: "Tarleton's foragers ran into Lauzun's French hussars and lancers outside Gloucester. In the cavalry clash a horse wounded by a French lance crashed into Tarleton's and threw him, and he was nearly captured. Mercer's militia stood firm and drove the British back. The Gloucester garrison was sealed in for the rest of the siege." },

  { id: 'fort_fair_lawn', name: 'Fort Fair Lawn', kind: 'raid', start: '1781-11-17', end: '1781-11-17', place: 'fort_fair_lawn',
    location: "Fair Lawn Plantation, Moncks Corner, Berkeley County, S.C.",
    outcome: 'allied', allies: [], crown: [], others: "Lt. Col. Hezekiah Maham and Col. Isaac Shelby (Marion's brigade); Capt. Murdock MacLaine (British)",
    strength: ['~380', '~50 in the fort, plus the hospital'], casualties: ['none', '~150 sick and wounded and staff captured'], approach: 0, withdrawal: 0,
    summary: "Maham's dragoons and Shelby's mountain riflemen captured the British hospital at Fair Lawn with some 150 patients and staff and 300 muskets. The garrison of the nearby fort did not come out. The British abandoned the post a week later and burned the plantation buildings." },

  { id: 'clouds_creek', name: "Cloud's Creek", kind: 'battle', start: '1781-11-17', end: '1781-11-17', place: 'clouds_creek',
    location: "Lick Creek, a branch of Cloud's Creek, near Batesburg-Leesville, Saluda County, S.C.",
    outcome: 'crown', allies: [], crown: [], others: "Capt. Sterling Turner (Patriot, killed); Maj. William Cunningham (Loyalist)",
    strength: ['~20–30', 'up to ~300'], casualties: ['~20 killed, most after surrendering', 'light'], approach: 0, withdrawal: 0,
    summary: "On his \"Bloody Scout\" through the backcountry, William Cunningham surrounded a small Patriot militia party in a house by the creek. When they surrendered, his men killed almost all of them, among them Captain James Butler and his son." },

  { id: 'hayes_station', name: "Hayes's Station", kind: 'battle', start: '1781-11-19', end: '1781-11-19', place: 'hayes_station',
    location: "Near Clinton, Laurens County, S.C. (monument)",
    outcome: 'crown', allies: [], crown: [], others: "Col. Joseph Hayes (Patriot, killed); Maj. William Cunningham (Loyalist)",
    strength: ['~20–35 militia', '~150–300'], casualties: ['Hayes and most of his men killed after surrendering (sources differ)', 'light'], approach: 0, withdrawal: 0,
    summary: "Two days after Cloud's Creek, Cunningham's raiders set fire to the blockhouse at Hayes's Station and forced the militia inside to surrender. Colonel Joseph Hayes and many of his men were then hanged or cut down. The killings hardened the backcountry's hatred of Loyalists for years." },

  { id: 'dorchester', name: 'Dorchester', kind: 'battle', start: '1781-12-01', end: '1781-12-01', place: 'dorchester_fort',
    location: "Fort Dorchester, Old Dorchester State Historic Site, Summerville, Dorchester County, S.C.",
    outcome: 'allied', allies: ['greene'], crown: [], others: "Col. Wade Hampton (Patriot cavalry); Maj. John Doyle (British)",
    strength: ['~400 (200 horse, 200 foot)', '~850'], casualties: ['light', 'light'], approach: 7, withdrawal: 3,
    summary: "Greene rode ahead of his army with a picked detachment. After skirmishes between the cavalry, the British, thinking the whole Southern Army was upon them, gave up Dorchester and fell back toward Charleston. It pushed the British line in to the edge of the city." },

  { id: 'wambaw_bridge', name: "Wambaw Bridge & Tidyman's Plantation", kind: 'battle', start: '1782-02-24', end: '1782-02-25', place: 'wambaw_bridge',
    location: "Wambaw Creek near McClellanville, Charleston County, S.C.",
    outcome: 'crown', allies: ['marion'], crown: [], others: "Lt. Col. Benjamin Thompson (British; later Count Rumford); Maj. William Benison and Col. Archibald McDonald (Patriot)",
    strength: ['~300–400', '~700'], casualties: ['~44 killed and captured, incl. Benison', 'few'], approach: 0, withdrawal: 0,
    summary: "With Marion away at the legislature, Benjamin Thompson's raiders surprised his brigade at Wambaw Creek and drove it across the bridge, killing Major Benison. Marion returned the next day and met Thompson at Tidyman's Plantation, where his men were routed again. Among the British were the Black Dragoons, a troop of formerly enslaved men." },

  { id: 'sharon', name: 'Sharon Plantation', kind: 'battle', start: '1782-06-24', end: '1782-06-24', place: 'sharon',
    location: "Old Louisville Road, about 6 miles west of Savannah, Chatham County, Georgia",
    outcome: 'allied', allies: ['wayne'], crown: [], others: "Emistisiguo (Upper Creek leader, killed)",
    strength: ['~500', 'a Creek war party (numbers differ)'], casualties: ['a few killed', 'Emistisiguo and a number of warriors killed'], approach: 0, withdrawal: 0,
    summary: "A Creek war party on its way to reinforce Savannah struck Wayne's camp before dawn and overran his guns. Wayne rallied his Continentals and drove them off; their leader Emistisiguo, a longtime British ally, was killed. Two weeks later the British left Savannah." },

  { id: 'savannah_evac', name: 'Evacuation of Savannah', kind: 'evacuation', start: '1782-07-11', end: '1782-07-11', place: 'savannah',
    location: "Savannah, Georgia",
    outcome: 'allied', allies: ['wayne'], crown: ['brown'], others: "Gov. Sir James Wright (British)",
    strength: ['—', 'the garrison, with Loyalists and several thousand enslaved people'], casualties: ['—', '—'], approach: 0, withdrawal: 0,
    summary: "After three and a half years of occupation, the British garrison, Governor Wright and thousands of Loyalists and enslaved people sailed from Savannah for Charleston, East Florida and Jamaica. Wayne's troops marched in the next day and the Georgia government returned to its capital." },

  { id: 'combahee', name: 'Combahee Ferry (Tar Bluff)', kind: 'battle', start: '1782-08-27', end: '1782-08-27', place: 'tar_bluff',
    location: "Tar Bluff on the Combahee River, Colleton County, S.C.",
    outcome: 'crown', allies: [], crown: [], others: "Lt. Col. John Laurens (killed) and Brig. Gen. Mordecai Gist (Patriot); Maj. William Brereton (British)",
    strength: ['~50–70 with Laurens', '~140–300'], casualties: ['Laurens and a few others killed, about 20 wounded or captured (sources differ)', 'light'], approach: 0, withdrawal: 0,
    summary: "A British foraging expedition came up the Combahee for rice. John Laurens, Washington's former aide, left his sickbed to lead a small detachment toward Chehaw Neck and was ambushed at Tar Bluff. He charged and was killed, one of the last Continental officers to die in the war. He had long pressed for enslaved men to be freed to fight for the American cause." },

  { id: 'wadboo_1782', name: 'Wadboo (Avenue of the Cedars)', kind: 'battle', start: '1782-08-29', end: '1782-08-29', place: 'wadboo',
    location: "Wadboo, near Moncks Corner, Berkeley County, S.C.",
    outcome: 'draw', allies: ['marion'], crown: [], others: "Maj. Thomas Fraser (British dragoons)",
    strength: ['~200', '~100 dragoons'], casualties: ['~3', '~17'], approach: 0, withdrawal: 0,
    summary: "Fraser's dragoons rode up the cedar avenue at Wadboo into the fire of Marion's men hidden along it, and fell back with losses. Short of powder after the British captured one of his wagons, Marion withdrew. It was his last fight; accounts disagree on who had the better of it." },

  { id: 'long_swamp', name: 'Long Swamp (Cherokee expedition)', kind: 'raid', start: '1782-10-01', end: '1782-10-17', place: 'long_swamp',
    location: "Long Swamp Creek, Cherokee County, Georgia (approximate; dates approximate)",
    outcome: 'allied', allies: ['pickens', 'clarke'], crown: [], others: "Cherokee towns allied with the British",
    strength: ['~400 mounted militia', '—'], casualties: ['light', 'towns burned; some killed (sources differ)'], approach: 15, withdrawal: 5,
    summary: "Pickens and Clarke led mounted militia deep into Cherokee country against towns that had sheltered Loyalist raiders, burning towns and crops. The expedition ended with Cherokee leaders agreeing to give up land in Georgia, one of several wartime land cessions forced on the Cherokee." },

  { id: 'dills_bluff', name: 'Dills Bluff (James Island)', kind: 'battle', start: '1782-11-14', end: '1782-11-14', place: 'dills_bluff',
    location: "James Island Creek, James Island, Charleston County, S.C.",
    outcome: 'crown', allies: [], crown: [], others: "Col. Tadeusz Kosciuszko and Capt. William Wilmot (killed) (Patriot); Maj. William Dancey (British)",
    strength: ['~70', '~300 with a gun'], casualties: ['5 killed incl. Wilmot, 5 wounded', '~5'], approach: 0, withdrawal: 0,
    summary: "Kosciuszko tried to ambush a British wood-cutting party on James Island, but the escort had been reinforced and he was outnumbered five to one. Captain William Wilmot was killed, probably the last Continental soldier to die in the Carolinas, and Kosciuszko barely escaped. It was the last fight of the war in South Carolina." },

  { id: 'charleston_evac', name: 'Evacuation of Charleston', kind: 'evacuation', start: '1782-12-14', end: '1782-12-14', place: 'charleston_wharf',
    location: "Charleston waterfront, S.C. (state marker 10-146)",
    outcome: 'allied', allies: ['greene', 'wayne', 'moultrie'], crown: ['leslie', 'cruger'], others: "Gov. John Mathews (S.C.)",
    strength: ['—', 'the garrison, with thousands of Loyalists and enslaved people'], casualties: ['—', '—'], approach: 0, withdrawal: 0,
    summary: "After 31 months of occupation, Leslie's army marched to the waterfront with Wayne's Continentals following them in, and a large fleet carried them, thousands of Loyalists and thousands of enslaved people away. Greene and Governor Mathews entered the city that afternoon. The war in the South was over; the peace was signed in Paris in 1783." },

  { id: 'hillsborough_raid', name: 'Hillsborough Raid', kind: 'raid', start: '1781-09-12', end: '1781-09-12', place: 'hillsborough',
    location: "Hillsborough, Orange County, N.C.",
    outcome: 'crown', allies: [], crown: [], others: "Col. David Fanning and Col. Hector McNeill (Loyalist); Gov. Thomas Burke (captured)",
    strength: ['town guard and militia', '~950 Loyalists'], casualties: ['~15 killed, ~200 captured incl. the governor', 'light'], approach: 0, withdrawal: 0,
    summary: "In a dawn raid, David Fanning's Loyalists rode into the North Carolina capital and carried off Governor Thomas Burke, members of his council, Continental officers and about 200 other prisoners, heading for the British post at Wilmington." },

  { id: 'lindleys_mill', name: "Lindley's Mill", kind: 'battle', start: '1781-09-13', end: '1781-09-13', place: 'lindleys_mill',
    location: "Cane Creek near Snow Camp, Alamance County, N.C. (approximate)",
    outcome: 'crown', allies: [], crown: [], others: "Gen. John Butler (Patriot militia); Col. David Fanning and Col. Hector McNeill (Loyalist; McNeill killed)",
    strength: ['~400', '~600–950 (sources differ)'], casualties: ['~24 killed, ~90 wounded, ~10 captured', '~27 killed, ~90 wounded'], approach: 0, withdrawal: 0,
    summary: "Butler's militia ambushed Fanning's column at the Cane Creek crossing to free Governor Burke. McNeill was killed in the first volley, but Fanning led a flank attack that drove the Patriots off after a four-hour fight. Fanning was badly wounded, yet his men got the governor through to Wilmington. It was one of the bloodiest militia fights in North Carolina." },

  { id: 'yorktown', name: 'Siege of Yorktown', kind: 'siege', radiusKm: 60, start: '1781-09-28', end: '1781-10-19', place: 'yorktown',
    location: "Yorktown, York County, Va.",
    outcome: 'allied', allies: ['gwashington', 'rochambeau', 'lafayette', 'lincoln', 'degrasse', 'wayne', 'steuben'], crown: ['cornwallis', 'tarleton'], others: 'Alexander Hamilton; Henry Knox (artillery)',
    strength: ['~8,800 Continentals, ~3,000 Virginia militia, ~7,800 French', '~9,000 incl. seamen'], casualties: ['~88 killed, ~301 wounded', '~156 killed, ~326 wounded, ~7,000 captured'], approach: 40, withdrawal: 0,
    summary: "The allied armies marched 450 miles from New York while de Grasse sealed the Chesapeake. Cornwallis was trapped. Allied guns opened on 9 October, Redoubts 9 and 10 fell to bayonet assaults on the night of 14 October, and a breakout across the York failed in a storm. On 19 October the British marched out to surrender. The war's last great campaign was over." },
];
